with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: Assemble the lumpia up to 4 hours ahead and refrigerate on a tray before frying. Fry just before serving.","Oil temperature is key, too cool and they'll be greasy; too hot and they'll burn. Use a thermometer or the wrapper test.","Serve with sweet chilli sauce, vinegar, or a quick dipping sauce made from soy sauce and a squeeze of lemon.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"b72be6bd-9e20-4c77-a5b9-e05a3b86357c"},{"notes":["Make ahead: marinate the chicken up to 4 hours. Fry it just before serving so it stays crispy.","The numbing heat comes from Sichuan peppercorn, the burn from dried chilies. Neither are mistakes, they're the point.","Serve with plain steamed rice or congee to cool your mouth between bites.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"5d1dbf57-f48c-4ec0-982f-e892b40f9241"},{"notes":["Shiro keeps for 3 days in the fridge. Reheat gently with a splash of water or stock, stirring often.","Shiro is a classic Ethiopian fasting dish: vegan, filling and humble."],"id":"5a54d1d3-f594-43fd-88ae-081319639424"},{"notes":["Serve over jasmine rice. One batch feeds one person with rice.","Make ahead: the curry keeps in the fridge for 3 days and reheats gently on the stove.","Swap peanut butter for ground peanuts (2 tbsp) stirred in at the end if you prefer texture.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Heat oil in a wok or wide pan over medium-high heat until shimmering, about 1 minute."},{"text":"Add curry paste and cook, stirring, for 1 minute until fragrant."},{"text":"Add chicken and stir-fry until the edges turn opaque, about 3 minutes."},{"text":"Pour in coconut milk and bring to a simmer, stirring gently, until the sauce is bubbling lightly and thickens slightly."},{"text":"Add peanut butter, fish sauce and palm sugar. Stir until peanut butter dissolves, about 2 minutes."},{"text":"Tear in the makrut lime leaf and simmer for 5 minutes until chicken is cooked through (75°C inside) and sauce is thick and glossy."},{"text":"Taste and adjust fish sauce or palm sugar to balance salty and sweet."},{"text":"Serve in a bowl with jasmine rice, topped with fresh Thai basil and chilli if using."}],"id":"3cf345e7-eebd-46b0-aca7-67d6a440257d"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the turmeric and crushed garlic, stirring for 30 seconds until fragrant and the oil turns golden yellow."},{"text":"Pour in the stock and coconut milk, stirring to combine. Bring to a simmer over medium-high heat until the broth is bubbling gently and steaming."},{"text":"Add the fish sauce and stir. Add the chicken slices and simmer gently for 8–10 minutes, stirring occasionally, until the chicken is cooked through."},{"text":"While the chicken cooks, bring a large pot of water to the boil. Add the noodles and cook according to packet directions until just tender. Drain well."},{"text":"Divide the noodles between two bowls. Ladle the hot broth and chicken over the top."},{"text":"Scatter the spring onions over each bowl. Serve with a lime wedge and fresh coriander on the side if you like. Squeeze the lime in before eating."}],"id":"76dc964f-0966-4f38-9b83-66915d26dd41"},{"notes":["Make it ahead: the curry tastes better the next day. Store in the fridge for up to 3 days, or freeze for a month.","Use whatever mushrooms you have, cremini, button, portobello all work. Firmer varieties hold their shape better in the long simmer."],"steps":[{"text":"Heat the oil in a large pot or deep pan over medium heat. Add the curry paste and cook, stirring, for 2 minutes until fragrant."},{"text":"Add the ginger and garlic, cook for another minute until fragrant, then pour in the coconut milk and stir well to combine."},{"text":"Add the mushrooms and stir to coat with the curry mixture. Cook for 5 minutes until they start to soften."},{"text":"Pour in the vegetable stock, tamarind paste and palm sugar. Stir until the sugar and tamarind dissolve, about 2 minutes."},{"text":"Bring to a gentle simmer and cook uncovered for 25–30 minutes, stirring occasionally, until the mushrooms are very tender and the curry has reduced and darkened. The sauce should coat the back of a spoon."},{"text":"Taste and adjust salt and sourness if needed. Serve hot with jasmine rice."}],"id":"bfd6329e-139c-4a01-b42a-116e34be6827"},{"diets":[],"notes":["Make them ahead: assemble the rolls, refrigerate up to 4 hours, then bake as directed.","The eggplants need to lose their water first – salt them well and don't rush this step.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"id":"43bf1c73-88de-460f-b224-b8c172c25ba4"},{"notes":["Make ahead: marinate the chicken overnight in the fridge for deeper flavour and better texture.","Leftovers: keeps in an airtight container in the fridge for 3 days; serve cold in bento or reheat gently.","Oil temperature matters: use a thermometer if you have one; too cool and it will be oily, too hot and the outside burns before the inside cooks.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Combine soy sauce, mirin, garlic, ginger and sesame oil in a bowl. Add the chicken pieces and toss to coat well. Cover and marinate in the fridge for at least 2 hours, preferably overnight."},{"text":"When ready to cook, remove the chicken from the marinade and place on paper towel. Pat dry thoroughly, this is important for crispiness. Reserve the marinade."},{"text":"Mix potato starch and plain flour together on a plate. Season the chicken pieces lightly with salt and white pepper, then coat each piece in the starch mixture, shaking off any excess."},{"text":"Heat neutral oil in a deep-sided pan or wok to 170°C. Working in batches so the pan isn't crowded, carefully lower the chicken into the oil."},{"text":"Fry for 8 to 10 minutes, turning halfway through, until the coating is golden and the thickest pieces are cooked through (75°C inside). Transfer to a paper towel to drain."},{"text":"Serve hot with lemon wedges and fresh coriander if you like. Any leftovers keep well cold in a bento box for the next day."}],"id":"8dd16d1b-296d-4f49-9a8e-4a763cfa1c24"},{"notes":["Make the filling up to a day ahead; store in the fridge. Assemble sambuusas up to 2 hours before frying.","If filo dries out as you work, cover the sheets with a damp tea towel.","Freeze uncooked sambuusas on a tray, then transfer to a container. Fry from frozen, adding a minute or two to the cooking time.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"58a47f13-1e17-4c48-9143-73818093fbf0"},{"notes":["Biscuits are best served warm from the oven. Leftovers can be split and toasted the next day.","For extra tender biscuits, chill the dough for 15 minutes before cutting and baking.","Make sure your butter and buttermilk are cold, this is what gives the biscuits their flaky layers."],"steps":[{"text":"Preheat oven to 200°C. Place a 25 cm cast-iron frying pan in the oven to heat."},{"text":"Whisk together flour, baking powder and salt in a large bowl. Add the cold butter cubes and use your fingertips to rub the mixture until it resembles coarse breadcrumbs with some pea-sized pieces of butter remaining."},{"text":"Make a well in the centre and pour in the cold buttermilk. Using a fork, gently mix until a shaggy dough just comes together, don't overwork it or the biscuits will be tough."},{"text":"Turn the dough out onto a lightly floured bench and gently pat it into a 2 cm thick round. Using a 7 cm biscuit cutter dipped in flour, cut out biscuits, pressing straight down without twisting."},{"text":"Carefully remove the hot frying pan from the oven and brush lightly with melted butter. Arrange biscuits in the pan, they should just touch each other."},{"text":"Brush the tops with a little more melted butter. Bake for 12–15 minutes, until golden brown on top and cooked through."},{"text":"Let cool in the pan for 2 minutes, then turn out onto a wire rack. Serve warm."}],"id":"179cacfb-8c92-43ab-92ad-d727e42127c7"},{"notes":["Use day-old or chilled rice, fresh hot rice gets mushy. If you only have hot rice, spread it on a plate to cool first.","Toast the Sichuan peppercorns in a dry pan for 1 minute before grinding for deeper flavour.","Leftovers keep in the fridge for 2 days and reheat well in a hot pan.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"7ba10ef1-daa2-49e8-89eb-a71f36afb946"},{"notes":["Maklouba keeps well in the fridge for up to 3 days. Reheat gently in a low oven wrapped in foil, or flash it in a hot pan to recrisp the bottom layer.","Use a non-stick or well-seasoned pot, this makes the flip much less stressful.","The spice blend is forgiving. If you don't have cardamom, add a pinch more cumin. If you don't have cinnamon, leave it out entirely."],"steps":[{"text":"Fry the eggplant slices in batches in hot oil until golden on both sides, about 4 minutes. Transfer to a plate lined with paper towel. This step is crucial, the eggplant will soften in the steam, so frying it first keeps its shape and flavour."},{"text":"In the same oil, fry the potato matchsticks in batches until just starting to turn golden, about 3 minutes. You want them still a bit firm because they'll cook further in the rice. Transfer to the paper towel plate."},{"text":"Fry the cauliflower florets until lightly golden, about 3 minutes. Set aside. You should have about 3 tablespoons of oil left in the pot; if not, add a little more."},{"text":"In the same pot, cook the sliced onions over medium heat, stirring, until soft and golden, about 8 minutes. Add the garlic and cook for 1 minute more until fragrant."},{"text":"Stir in the cumin, coriander, cardamom and cinnamon, cooking for 1 minute. You'll smell the spices bloom, this is when their flavour becomes most alive. Add the rice and stir to coat it in the spiced oil, cooking for 2 minutes."},{"text":"Layer the rice mixture back into the pot in this order: half the rice on the bottom, then the eggplant, potato and cauliflower mixed together, then the remaining rice on top. Press down gently to compact the layers. Pour the warm stock over carefully."},{"text":"Bring to a boil, then reduce heat to low. Cover with foil, then place the lid on top, the foil traps steam, which cooks the rice evenly. Cook for 20 minutes until the rice is tender and the stock is absorbed. Listen: when the liquid stops bubbling, you're done."},{"text":"Let it rest, covered, for 5 minutes. Run a thin knife around the edges of the pot to loosen it. Place a large platter over the pot, and in one confident motion, flip the pot onto the platter. Lift the pot away slowly. You should see a golden crust on top."},{"text":"Serve warm with generous dollops of Greek yoghurt and fresh parsley if you like. Eat it while the crust is still crispy."}],"id":"cc1d39fc-4f66-4032-885e-eefb12f755e9"},{"notes":["Fesenjan tastes better the next day. Make it ahead and reheat gently.","If you can't find pomegranate molasses, use equal parts pomegranate juice and lemon juice reduced in a pan until syrupy, or use a mix of pomegranate juice and balsamic vinegar.","Serve with tahdig, rice cooked until the bottom catches and caramelizes in a thin, crispy layer.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large, heavy pot over medium-high heat. Season the chicken generously with salt and pepper. Working in batches, brown the chicken skin-side down for 5 minutes, then turn and brown the other side for 3 minutes. Set aside."},{"text":"In the same pot, add the onion halves and cook, stirring occasionally, until they soften and colour, about 8 minutes. Add the tomato paste and cook for 1 minute, stirring."},{"text":"Stir in the walnuts, cinnamon and turmeric. Cook for 2 minutes until fragrant."},{"text":"Pour in the pomegranate juice and pomegranate molasses, scraping up any brown bits from the bottom of the pot. Return the chicken to the pot, skin-side up. Bring to a simmer until the sauce is bubbling gently and starting to thicken."},{"text":"Cover and cook on low heat for 50–60 minutes, until the chicken is tender and cooked through and the sauce has deepened in colour and thickened slightly. Taste and adjust the salt, pepper, and balance of sweet and sour as needed."},{"text":"Remove the onion halves. Serve over rice, with fresh coriander if you like it."}],"id":"fccf0bf5-45fd-479e-8151-7d2ab6c16e94"},{"notes":["Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Heat the oil in a large heavy-bottomed pot over medium heat. Add the flour and stir constantly for 8 to 10 minutes, until the roux is deep golden brown, this is the foundation of everything. Don't rush it; if it starts to burn, pull it off the heat for a moment."},{"text":"Add the onion, capsicum, and celery to the roux. Stir well and cook for about 5 minutes, until the vegetables soften and release their flavour. This is the holy trinity, cher."},{"text":"Push the vegetables to the side, add the sausage, and let it sear for 2 to 3 minutes. Stir in the garlic, cayenne, paprika, thyme, and oregano, cooking for 1 more minute until fragrant."},{"text":"Pour in the crushed tomatoes and chicken stock. Scrape the bottom of the pot to loosen any browned bits. Bring to a gentle boil until bubbling, then reduce the heat to medium-low. Stir in the rice, making sure it's covered by liquid."},{"text":"Simmer, stirring occasionally, for about 20 minutes, until the rice is nearly tender and most of the liquid is absorbed."},{"text":"Gently fold in the prawns, crab, and oysters (if using). Cook for 3 to 4 minutes, until the prawns are pink and cooked through and the oysters have just firmed up."},{"text":"Season to taste with salt and pepper. Serve hot, scattered with fresh parsley if you like."}],"id":"14ca1271-d6df-47e0-a6c8-5cb39d61c636"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"notes":["Make sure your dosa batter is at room temperature; cold batter won't spread and cook evenly.","If your batter is too thick, add a splash of water, it should be pourable but thicker than a dosa batter.","Uttapam keeps for a day in an airtight container and reheats well in a toaster or griddle."],"steps":[{"text":"Heat a non-stick griddle or heavy-bottomed pan over medium heat and lightly oil it."},{"text":"Pour 1/4 cup of batter onto the griddle and gently spread into a thick round, about 8 cm across. Don't thin it out like a dosa, keep it thick and spongy."},{"text":"Let it cook, undisturbed, for about 2 minutes until the bottom is golden and set."},{"text":"Sprinkle a small handful of chopped onion, tomato, green chilli and coriander (if using) over the top. Press gently into the batter."},{"text":"Flip carefully and cook the other side for another 2 minutes until golden. If the top toppings aren't cooked enough, cover the pan with a lid for 30 seconds."},{"text":"Transfer to a plate and repeat with the remaining batter and toppings."},{"text":"Serve hot with sambar, rasam or fresh coconut chutney."}],"id":"788f0fca-b612-486d-a6ce-fed1f3c19960"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;